/** 筛选不会产生回路的混音总线发送目标。 */ function audioRouteOptions(bus:AudioMixerBusSettings){return audioSettings.mixer.buses.filter(/** 遍历候选总线的父链和启用发送，遇到当前总线则拒绝以防回路。 */ candidate=>{if(candidate.id===bus.id)return false;const seen=new Set<string>(),pending=[candidate.id];while(pending.length){const id=pending.pop()!;if(id===bus.id)return false;if(seen.has(id))continue;seen.add(id);const current=audioSettings.mixer.buses.find(/* 比较 entry.id 与 id，返回严格相等的判断结果。 */ entry=>entry.id===id);if(current?.parent)pending.push(current.parent);for(const send of current?.sends??[])if(send.enabled)pending.push(send.target)}return true})}
