const unregisterThemeDraft = registerStudioDraftOwner({ read: /* 调用 draftCandidate('theme') 并返回调用结果。 */ () => draftCandidate('theme'), discard: /* 调用 discardDraft('theme') 并返回调用结果。 */ () => discardDraft('theme') }), unregisterLocaleDraft = registerStudioDraftOwner({ read: /* 调用 draftCandidate('localization') 并返回调用结果。 */ () => draftCandidate('localization'), discard: /* 调用 discardDraft('localization') 并返回调用结果。 */ () => discardDraft('localization') })
