/** 导出当前语言表为 CSV，下载后释放对象地址。 */ function exportCsv() { if (!localeDraft.value) return; const blob = new Blob([exportLocalizationCsv(localeDraft.value)], { type: 'text/csv;charset=utf-8' }), anchor = document.createElement('a'); anchor.href = URL.createObjectURL(blob); anchor.download = `${localeDraft.value.locale}.csv`; anchor.click(); URL.revokeObjectURL(anchor.href) }
