/** 添加默认混音总线并提交音频设置。 */ function addBus() { const index = audioSettings.mixer.buses.length + 1; audioSettings.mixer.buses.push({ id: `Bus-${crypto.randomUUID()}`, name: `Bus ${index}`, gain: 1, mute: false, solo: false, parent: 'Master', voiceLimit: 32, sends: [], effects: [], automation: [], automationLoopSeconds: 0 }); commitAudio() }
